sys_script_include.script:
var Cisco_Sceure_Access_Poll_Appliaction_List_Details = Class.create();
Cisco_Sceure_Access_Poll_Appliaction_List_Details.prototype = {
	initialize: function () {
	},

	fetchAndSyncApplicationLists: function () {
		try {
			gs.info("[Cisco Secure AccessAPP-LIST] === Script Started ===");

			// 1. Fetch existing ServiceNow application list records into a map keyed by name
			var snowRecords = {};
			var grSnow = new GlideRecord("u_cisco_secure_access_application_list");
			grSnow.query();
			while (grSnow.next()) {
				var name = grSnow.getValue("u_application_list_name");
				if (name) {
					snowRecords[name] = {
						sys_id: grSnow.getUniqueValue(),
						active_status: grSnow.getValue("u_active_status"),
						resource_group_for: grSnow.getValue("u_resource_group_for"),
						application_list_id: grSnow.getValue("u_application_list_id"),
						is_default: grSnow.getValue("u_is_default"),
						created_at: grSnow.getValue("u_created_at"),
						modified_at: grSnow.getValue("u_modified_at")
					};
				}
			}
			gs.info("[Cisco Secure AccessAPP-LIST] ServiceNow records fetched. Count=" + Object.keys(snowRecords).length);

			// 2. Fetch all Cisco Secure Access application lists from SSE API
			var token = new CiscoSecureAccessGetToken().getLatestAccessToken();
			var r = new sn_ws.RESTMessageV2("Cisco Secure Access Application List", "Get Application List");
			r.setRequestHeader("Authorization", "Bearer " + token);
			r.setRequestHeader("Accept", "application/json");
			var response = r.execute();
			var status = response.getStatusCode();
			var body = response.getBody();

			if (status !== 200) {
				gs.error("[Cisco Secure AccessAPP-LIST] Cisco Secure Access API Error: " + status + " - " + body);
				// return;
			}

			var parsed = JSON.parse(body);
			gs.info("[Cisco Secure AccessAPP-LIST] Raw API response: " + body);

			// Use 'results' as the array of application lists
			var csaItems = parsed.results || [];
			if (!Array.isArray(csaItems)) {
				gs.error("[Cisco Secure AccessAPP-LIST] Unexpected Cisco Secure Access API response format.");
				// return;
			}
			gs.info("[Cisco Secure AccessAPP-LIST] Cisco Secure Access records fetched. Count=" + csaItems.length);

			// 3. Update or insert ServiceNow rows that match Cisco Secure Access by name
			var updatedCount = 0, insertedCount = 0;
			for (var i = 0; i < csaItems.length; i++) {
				var item = csaItems[i];
				var name = item.applicationListName;
				var gr;
				if (snowRecords[name]) {
					// Update existing
					var existing = snowRecords[name];
					gr = new GlideRecord("u_cisco_secure_access_application_list");
					if (gr.get(existing.sys_id)) {
						var needUpdate = false;
						if (!existing.application_list_id && item.applicationListId) { gr.setValue("u_application_list_id", item.applicationListId); needUpdate = true; }
						if (!existing.is_default && item.isDefault !== undefined) { gr.setValue("u_is_default", item.isDefault ? "true" : "false"); needUpdate = true; }
						if (!existing.created_at && item.createdAt) { gr.setValue("u_created_at", item.createdAt); needUpdate = true; }
						if (!existing.modified_at && item.modifiedAt) { gr.setValue("u_modified_at", item.modifiedAt); needUpdate = true; }
						if (needUpdate) {
							gr.update();
							updatedCount++;
							gs.info("[Cisco Secure AccessAPP-LIST] Updated SNOW record by name: " + name + " (List ID: " + item.applicationListId + ")");
						} else {
							gs.info("[Cisco Secure AccessAPP-LIST] No missing fields for: " + name);
						}
					}
				}
			}

			gs.info("[Cisco Secure AccessAPP-LIST] Completed. Records updated=" + updatedCount + ", inserted=" + insertedCount);

		} catch (e) {
			gs.error("[Cisco Secure AccessAPP-LIST] Script Error: " + e.message);
		}
	},

	type: 'Cisco_Sceure_Access_Poll_Appliaction_List_Details'
};
